// Actions change a small part of the reunion, without inventing a fourth ending
// or claiming that a lure worked when the creature was still watching us.
export function endingParagraphs(id, flags = {}) {
  const paragraphs = [...(ENDINGS[id]?.paragraphs || [])];
  if (!paragraphs.length) return paragraphs;
  let recollection = '';
  if (flags.bellUsed) {
    recollection = '物置の呼び鐘を鳴らしたと話すと、修司は私の無線の電源を切った。静かになったあとも、耳の奥で鐘の音が続いていた。';
  } else if (flags.shutterUsed || flags.shutterClosed) {
    recollection = flags.shutterClosed
      ? '閉めてきた雨戸のことを、修司に話した。「あれは、そのままでいい」とだけ言われた。備品の一覧に、留め金を直すと書いてあったのを思い出した。'
      : '雨戸を開け直したことだけは、修司に言わなかった。管理棟の窓を閉めるとき、今度は留め金まで確かめた。';
  }
  if (recollection) paragraphs.splice(Math.min(2, paragraphs.length), 0, recollection);
  return paragraphs;
}
